create or replace function public.repair_published_package_source_hash(p_package_version_id uuid,p_source_sha256 text,p_reason text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare v_repair_id uuid:=gen_random_uuid(); v_org_id uuid; v_package_id uuid; v_status text; v_original_published_at timestamptz; v_old_snapshot_hash text; v_old_source_sha text; begin if coalesce(auth.role(),'')<>'service_role' and session_user<>'postgres' then raise exception 'Source hash repair requires service_role' using errcode='42501'; end if; if p_source_sha256 !~ '^[0-9a-f]{64}$' then raise exception 'source SHA-256 must be 64 lowercase hex characters'; end if; if length(trim(coalesce(p_reason,'')))<8 then raise exception 'A repair reason of at least 8 characters is required'; end if; select p.organization_id,p.id,v.status,v.published_at,v.snapshot_hash,v.source_metadata->>'sourceSha256' into v_org_id,v_package_id,v_status,v_original_published_at,v_old_snapshot_hash,v_old_source_sha from public.test_package_versions v join public.test_packages p on p.id=v.package_id where v.id=p_package_version_id for update of v; if v_org_id is null then raise exception 'Package Version not found'; end if; if v_status<>'published' then raise exception 'Package Version must be published'; end if; insert into public.package_version_text_repairs(id,organization_id,package_version_id,reason,status,requested_by_user_id) values(v_repair_id,v_org_id,p_package_version_id,trim(p_reason),'running',public.current_staff_user_id()); perform set_config('app.package_text_repair_id',v_repair_id::text,true); update public.test_package_versions set status='draft',published_at=null where id=p_package_version_id; update public.test_package_versions set snapshot_hash='sha256:'||p_source_sha256,source_metadata=source_metadata||jsonb_build_object('sourceSha256',p_source_sha256,'finalSourceSha256',p_source_sha256,'sourceHashRepairedAt',now()),status='published',published_at=v_original_published_at where id=p_package_version_id; update public.test_packages set source_metadata=source_metadata||jsonb_build_object('sourceSha256',p_source_sha256,'finalSourceSha256',p_source_sha256,'sourceHashRepairedAt',now()) where id=v_package_id; update public.package_version_text_repairs set status='completed',completed_at=now(),repairs=jsonb_build_array(jsonb_build_object('scope','package_source_hash','before',jsonb_build_object('snapshotHash',v_old_snapshot_hash,'sourceSha256',v_old_source_sha),'after',jsonb_build_object('snapshotHash','sha256:'||p_source_sha256,'sourceSha256',p_source_sha256))) where id=v_repair_id; perform set_config('app.package_text_repair_id','',true); return jsonb_build_object('repairId',v_repair_id,'packageVersionId',p_package_version_id,'status','published','sourceSha256',p_source_sha256); end; $$; revoke execute on function public.repair_published_package_source_hash(uuid,text,text) from public,anon,authenticated; grant execute on function public.repair_published_package_source_hash(uuid,text,text) to service_role;;
